        fa: "و آن كيفر و عقاب را كه براى خصم من مهيا ساخته‏اى در آينه دل من عيان كن و سبب خرسندى منش گردان، در برابر آنچه براى من مقدر ساخته‏ اى و باعث اطمينان من است به آنچه براى من اختيار كرده ‏اى.",
