    title: "دعای هجدهم صحیفه سجادیه",
    description:
      "دعای آن حضرت است هنگامی که خطری از او می‌گذشت یا حاجتش به سرعت برآورده می‌شد",
    audio: "",
    sections: [
      {
        ar: "اَللَّهُمَّ لَكَ الْحَمْدُ عَلَى حُسْنِ قَضَائِكَ وَ بِمَا صَرَفْتَ عَنِّي مِنْ بَلاَئِكَ",
        fa: "اى خداوند، حمد باد تو را بر آن حسن تقدير كه نصيب من ساخته ‏اى و آن بلاها كه از من بگردانيده‏ اى.",
      },
      {
        ar: "فَلاَ تَجْعَلْ حَظِّي مِنْ رَحْمَتِكَ مَا عَجَّلْتَ لِي مِنْ عَافِيَتِكَ فَأَكُونَ قَدْ شَقِيتُ بِمَا أَحْبَبْتُ وَ سَعِدَ غَيْرِي بِمَا كَرِهْتُ",
        fa: "چنان مباد كه اين تندرستى كه اكنون مرا ارزانى داشته‏ اى، همه بهره من از رحمت تو باشد، تا آنچه دوست مى ‏داشته ‏ام سبب شوربختى من شود و ديگرى، از آنچه من ناخوش مى ‏داشته‏ ام به سعادت رسد.",
      },
      {
        ar: "وَ إِنْ يَكُنْ مَا ظَلِلْتُ فِيهِ أَوْ بِتُّ فِيهِ مِنْ هَذِهِ الْعَافِيَةِ بَيْنَ يَدَيْ بَلاَءٍ لاَ يَنْقَطِعُ وَ وِزْرٍ لاَ يَرْتَفِعُ فَقَدِّمْ لِي مَا أَخَّرْتَ وَ أَخِّرْ عَنِّي مَا قَدَّمْتَ",
        fa: "اى خداوند، اگر اين تندرستى كه مرا نصيب كرده‏ اى و من شب و روزم را در آن به سر مى ‏آورم نشانه بلايى باشد بر دوام يا وبالى پايدار، پس آنچه را كه واپس داشته ‏اى پيش افكن و آنچه را كه پيش افكنده ‏اى واپس دار.",
      },
      {
        ar: "فَغَيْرُ كَثِيرٍ مَا عَاقِبَتُهُ الْفَنَاءُ وَ غَيْرُ قَلِيلٍ مَا عَاقِبَتُهُ الْبَقَاءُ وَ صَلِّ عَلَى مُحَمَّدٍ وَ آلِهِ",
        fa: "زيرا چيزى كه به فنا انجامد بس ناچيز است هر چند فراوان بود، و چيزى كه به بقا انجامد بسيارى است هر چند اندك نمايد. و بر محمد و خاندانش درود بفرست.",
      },
    ],
    commentary: "",
