        fa: "اى خداوند، از نادانى خود، از درگاه تو، پوزش مى ‏طلبم و بخشايش كردار بدم را از تو مى ‏خواهم. به احسان خويش مرا در كنف رحمت خود جاى ده و به فضل و كرم خويش در پرده عافيت خود بپوشان.",
