        fa: "و حمد باد تو را كه سپاس احسان و انعام خود به من الهام فرمودى. بر محمد و خاندانش درود بفرست و روزى من به آسانى به من برسان و به هر مقدار كه براى من مقدر مى‏ فرمايى خرسند گردان‏",
