        fa: "و به حصه‏اى كه براى من مقرر مى ‏دارى خشنودم ساز و چنان كن كه هر چه از جسم من مى ‏كاهد و از عمر من سپرى مى‏ شود، در راه فرمانبردارى تو باشد، كه تو بهترين روزى دهندگانى.",
