        fa: "بار خدايا، همه آفريدگان معترفند كه هر كه را عقوبت كنى بر او ستم نكرده ‏اى و همگان بر اين گواهند كه هر كه را از عذاب رهايى بخشى در حق او احسان كرده ‏اى و همه اقرار مى‏ كنند كه حق عبادت و شكر تو را آن چنان كه در خور آن هستى به جاى نياورده ‏اند",
