        fa: "آن سان كه من از آنان در گذشته‏ ام، تو نيز از من در گذر و آن سان كه من در حق آنان دعاى خير كرده ‏ام تو نيز رحمت خود از من دريغ مدار، تا هم من و هم ايشان به بركت فضل و احسان تو به سعادت رسيم و رهايى يابيم.",
