        fa: "پس بر محمد و خاندان او درود بفرست و مرا كه بر خود ستم كرده‏ام عفو كن و رحمت خود بر گمار تا سبكبارم سازد. چه بسا رحمت تو گنهكاران را رسد و چه بسا ستمكاران كه مشمول عفو تو گردند.",
