        fa: "منزه است خداى كه چگونه شگفت تدبيرى در كار آفرينش تو كرد و لطف و زيبايى صنع خويش را نمودار ساخت تو را كليد قفل بسته زمان و ظهورت را هر ماه نو براى تاريخ و تعيين حادثه نو قرار داد",
