        fa: "چنان كن كه روز عيد از شمار بهترين روزهايى باشد كه بر ما گذشته و عفو تو را به سوى ما آورده و گناه ما را زدوده است. بار خدايا، گناهان آشكار و نهان ما را بيامرز.",
