        fa: "اى خداوند، همانند مزدى كه او را مى‏دهى، از خزانه بى ‏نيازيت به ما نيز ارزانى دار و چند برابر آن از فضل خود عطا فرماى، كه خزاين فضل تو را نقصان نيست،",
