        fa: "اى خداوند، روزى ما ساز خوف از عقاب جهنم را و شوق به نعيم بهشت را، تا لذت آنچه را كه از تو خواسته‏ ايم در يابيم و از اندوه آنچه از آن به تو پناه مى ‏آوريم وارهيم.",
