        fa: "بار خدايا، تو حجتهاى خود، در پى يكديگر و به يارى يكديگر اقامه كرده ‏اى و دليلهاى خود از دير باز آشكار ساخته‏اى و پيش از اين مردم را از عذاب خود بيم داده‏ اى و از روى تلطف ترغيب كرده ‏اى‏",
