        fa: "بار خدايا، خاموشى مى‏ گزينم، كه از ستايشگريت ناتوانم و زبان بر مى‏بندم، كه از تمجيد و تكريمت عاجزم. اى خداى من، نهايت كوشش من اعتراف به درماندگى من است، نه آنكه نخواهم، كه نمى‏ توانم.",
